Literal.Value:
'{
  "padding": 0,
  "params": [
    {
      "name": "title",
      "value": "Spend"
    },
    {
      "name": "targetLabel",
      "value": "budget"
    },
    {
      "name": "aheadText",
      "value": "ahead of pace"
    },
    {
      "name": "behindText",
      "value": "behind pace"
    },
    {
      "name": "toGoText",
      "value": "to go"
    },
    {
      "name": "overText",
      "value": "over target"
    },
    {
      "name": "valueFormat",
      "value": "auto"
    },
    {
      "name": "prefix",
      "value": "$"
    },
    {
      "name": "pctFormat",
      "value": ".0%"
    },
    {
      "name": "noDataText",
      "value": "n/a"
    },
    {
      "name": "higherIsBetter",
      "value": false
    },
    {
      "name": "colorGood",
      "expr": "pbiColor(''good'')"
    },
    {
      "name": "colorBad",
      "expr": "pbiColor(''bad'')"
    },
    {
      "name": "arrowUp",
      "value": "▲"
    },
    {
      "name": "arrowDown",
      "value": "▼"
    },
    {
      "name": "arrowFlat",
      "value": "►"
    },
    {
      "name": "cardColor",
      "value": "#FFFFFF"
    },
    {
      "name": "borderColor",
      "value": "#E1DFDD"
    },
    {
      "name": "borderWidth",
      "value": 1
    },
    {
      "name": "cardRadius",
      "value": 4
    },
    {
      "name": "valueColor",
      "expr": "pbiColor(0, -0.5)"
    },
    {
      "name": "labelColor",
      "value": "#605E5C"
    },
    {
      "name": "barColor",
      "expr": "pbiColor(0)"
    },
    {
      "name": "trackColor",
      "value": "#EDEBE9"
    },
    {
      "name": "paceColor",
      "value": "#252423"
    },
    {
      "name": "stacked",
      "expr": "width < 2.4 * height"
    },
    {
      "name": "unit",
      "expr": "stacked ? clamp(min(width / 240, height / 160), 0.5, 3) : clamp(min(width / 300, height / 90), 0.5, 3)"
    },
    {
      "name": "pad",
      "expr": "14 * unit"
    },
    {
      "name": "top0",
      "expr": "max(0, (height - (stacked ? 160 : 90) * unit) / 2)"
    },
    {
      "name": "titleSize",
      "expr": "(stacked ? 13 : 12) * unit"
    },
    {
      "name": "titleY",
      "expr": "top0 + (stacked ? 26 : 22) * unit"
    },
    {
      "name": "valueSize",
      "expr": "(stacked ? 38 : 28) * unit"
    },
    {
      "name": "valueY",
      "expr": "top0 + (stacked ? 76 : 53) * unit"
    },
    {
      "name": "headSize",
      "expr": "12 * unit"
    },
    {
      "name": "headX",
      "expr": "stacked ? pad : width - pad"
    },
    {
      "name": "headY",
      "expr": "top0 + (stacked ? 98 : 22) * unit"
    },
    {
      "name": "headAlign",
      "expr": "stacked ? ''left'' : ''right''"
    },
    {
      "name": "statusSize",
      "expr": "(stacked ? 12 : 11.5) * unit"
    },
    {
      "name": "statusX",
      "expr": "stacked ? pad : width - pad"
    },
    {
      "name": "statusY",
      "expr": "top0 + (stacked ? 148 : 52) * unit"
    },
    {
      "name": "statusAlign",
      "expr": "stacked ? ''left'' : ''right''"
    },
    {
      "name": "barX0",
      "expr": "pad"
    },
    {
      "name": "barX1",
      "expr": "width - pad"
    },
    {
      "name": "barY0",
      "expr": "top0 + (stacked ? 110 : 63) * unit"
    },
    {
      "name": "barY1",
      "expr": "top0 + (stacked ? 124 : 73) * unit"
    },
    {
      "name": "barRadius",
      "expr": "(barY1 - barY0) / 2"
    },
    {
      "name": "paceOverhang",
      "expr": "4 * unit"
    }
  ],
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "Value",
          "as": "vSum"
        },
        {
          "op": "valid",
          "field": "Value",
          "as": "vN"
        },
        {
          "op": "sum",
          "field": "Target",
          "as": "tgSum"
        },
        {
          "op": "valid",
          "field": "Target",
          "as": "tgN"
        },
        {
          "op": "mean",
          "field": "Percent Elapsed",
          "as": "peMean"
        },
        {
          "op": "valid",
          "field": "Percent Elapsed",
          "as": "peN"
        }
      ]
    },
    {
      "calculate": "datum.vN > 0 ? datum.vSum : null",
      "as": "v"
    },
    {
      "calculate": "datum.tgN > 0 ? datum.tgSum : null",
      "as": "tg"
    },
    {
      "calculate": "datum.peN > 0 ? clamp(datum.peMean, 0, 1) : null",
      "as": "pe"
    },
    {
      "calculate": "isValid(datum.v) && isValid(datum.tg) && datum.tg !== 0 ? datum.v / datum.tg : null",
      "as": "r"
    },
    {
      "calculate": "isValid(datum.r) && isValid(datum.pe) ? datum.r - datum.pe : null",
      "as": "pg"
    },
    {
      "calculate": "isValid(datum.pg) ? (higherIsBetter ? 1 : -1) * datum.pg : 0",
      "as": "g"
    },
    {
      "calculate": "isValid(datum.pg) ? (datum.g >= 0 ? colorGood : colorBad) : barColor",
      "as": "fillColor"
    },
    {
      "calculate": "isValid(datum.v) && isValid(datum.tg) ? datum.tg - datum.v : null",
      "as": "rem"
    },
    {
      "calculate": "(!isValid(datum.v) || !isFinite(datum.v) ? noDataText : valueFormat !== ''auto'' ? format(datum.v, valueFormat) : (datum.v < 0 ? ''−'' : '''') + prefix + format(abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1), abs(datum.v) / (abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.v) >= 999.5e6 ? 1e9 : abs(datum.v) >= 999.5e3 ? 1e6 : abs(datum.v) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.v) >= 999.5e6 ? ''bn'' : abs(datum.v) >= 999.5e3 ? ''M'' : abs(datum.v) >= 999.5 ? ''K'' : ''''))",
      "as": "valueText"
    },
    {
      "calculate": "(!isValid(datum.tg) || !isFinite(datum.tg) ? noDataText : valueFormat !== ''auto'' ? format(datum.tg, valueFormat) : (datum.tg < 0 ? ''−'' : '''') + prefix + format(abs(datum.tg) / (abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1), abs(datum.tg) / (abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.tg) >= 999.5e6 ? 1e9 : abs(datum.tg) >= 999.5e3 ? 1e6 : abs(datum.tg) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.tg) >= 999.5e6 ? ''bn'' : abs(datum.tg) >= 999.5e3 ? ''M'' : abs(datum.tg) >= 999.5 ? ''K'' : ''''))",
      "as": "targetText"
    },
    {
      "calculate": "(!isValid(datum.r) || !isFinite(datum.r) ? noDataText : format(datum.r, pctFormat))",
      "as": "ratioText"
    },
    {
      "calculate": "datum.ratioText + '' of '' + datum.targetText + (stacked ? '' '' + targetLabel : '''')",
      "as": "headText"
    },
    {
      "calculate": "isValid(datum.rem) ? abs(datum.rem) : null",
      "as": "remAbs"
    },
    {
      "calculate": "!isValid(datum.rem) ? noDataText : datum.rem > 0 ? (!isValid(datum.remAbs) || !isFinite(datum.remAbs) ? noDataText : valueFormat !== ''auto'' ? format(datum.remAbs, valueFormat) : (datum.remAbs < 0 ? ''−'' : '''') + prefix + format(abs(datum.remAbs) / (abs(datum.remAbs) >= 999.5e6 ? 1e9 : abs(datum.remAbs) >= 999.5e3 ? 1e6 : abs(datum.remAbs) >= 999.5 ? 1e3 : 1), abs(datum.remAbs) / (abs(datum.remAbs) >= 999.5e6 ? 1e9 : abs(datum.remAbs) >= 999.5e3 ? 1e6 : abs(datum.remAbs) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.remAbs) >= 999.5e6 ? 1e9 : abs(datum.remAbs) >= 999.5e3 ? 1e6 : abs(datum.remAbs) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.remAbs) >= 999.5e6 ? ''bn'' : abs(datum.remAbs) >= 999.5e3 ? ''M'' : abs(datum.remAbs) >= 999.5 ? ''K'' : '''')) + '' '' + toGoText : datum.rem < 0 ? (!isValid(datum.remAbs) || !isFinite(datum.remAbs) ? noDataText : valueFormat !== ''auto'' ? format(datum.remAbs, valueFormat) : (datum.remAbs < 0 ? ''−'' : '''') + prefix + format(abs(datum.remAbs) / (abs(datum.remAbs) >= 999.5e6 ? 1e9 : abs(datum.remAbs) >= 999.5e3 ? 1e6 : abs(datum.remAbs) >= 999.5 ? 1e3 : 1), abs(datum.remAbs) / (abs(datum.remAbs) >= 999.5e6 ? 1e9 : abs(datum.remAbs) >= 999.5e3 ? 1e6 : abs(datum.remAbs) >= 999.5 ? 1e3 : 1) < 10 ? ((abs(datum.remAbs) >= 999.5e6 ? 1e9 : abs(datum.remAbs) >= 999.5e3 ? 1e6 : abs(datum.remAbs) >= 999.5 ? 1e3 : 1) > 1 ? ''.1f'' : ''.2~f'') : '',.0f'') + (abs(datum.remAbs) >= 999.5e6 ? ''bn'' : abs(datum.remAbs) >= 999.5e3 ? ''M'' : abs(datum.remAbs) >= 999.5 ? ''K'' : '''')) + '' '' + overText : ''on '' + targetLabel",
      "as": "gapText"
    },
    {
      "calculate": "isValid(datum.pg) ? format(abs(datum.pg) * 100, ''.0f'') : ''''",
      "as": "paceN"
    },
    {
      "calculate": "isValid(datum.pg) ? (!isValid(datum.pg) ? '''' : datum.pg > 0 ? arrowUp : datum.pg < 0 ? arrowDown : arrowFlat) + '' '' + datum.paceN + (datum.paceN === ''1'' ? '' pt '' : '' pts '') + (datum.pg >= 0 ? aheadText : behindText) : ''''",
      "as": "paceText"
    },
    {
      "calculate": "isValid(datum.pg) ? datum.paceText : datum.gapText",
      "as": "statusText"
    },
    {
      "calculate": "isValid(datum.rem) && datum.rem < 0 ? (higherIsBetter ? colorGood : colorBad) : labelColor",
      "as": "overColor"
    },
    {
      "calculate": "isValid(datum.pg) ? datum.fillColor : datum.overColor",
      "as": "statusColor"
    },
    {
      "calculate": "stacked && isValid(datum.pg) ? datum.gapText : ''''",
      "as": "restText"
    },
    {
      "calculate": "max(1, isValid(datum.r) ? datum.r : 0)",
      "as": "barMax"
    },
    {
      "calculate": "barX0 + clamp(isValid(datum.r) ? datum.r : 0, 0, datum.barMax) / datum.barMax * (barX1 - barX0)",
      "as": "fillX"
    },
    {
      "calculate": "barX0 + (barX1 - barX0) / datum.barMax",
      "as": "targetX"
    },
    {
      "calculate": "isValid(datum.pe) ? barX0 + datum.pe / datum.barMax * (barX1 - barX0) : null",
      "as": "paceX"
    },
    {
      "calculate": "barX0",
      "as": "bx0"
    },
    {
      "calculate": "barX1",
      "as": "bx1"
    },
    {
      "calculate": "barY0",
      "as": "by0"
    },
    {
      "calculate": "barY1",
      "as": "by1"
    },
    {
      "calculate": "barY0 - paceOverhang",
      "as": "py0"
    },
    {
      "calculate": "barY1 + paceOverhang",
      "as": "py1"
    },
    {
      "calculate": "isValid(datum.pe) ? format(datum.pe, ''.0%'') + '' of the period gone'' : ''no pace bound''",
      "as": "tipPace"
    }
  ],
  "layer": [
    {
      "description": "Card background and border, inset by half the border so the container never clips it",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "rect",
        "x": {
          "expr": "borderWidth / 2"
        },
        "y": {
          "expr": "borderWidth / 2"
        },
        "x2": {
          "expr": "width - borderWidth / 2"
        },
        "y2": {
          "expr": "height - borderWidth / 2"
        },
        "fill": {
          "expr": "cardColor"
        },
        "stroke": {
          "expr": "borderColor"
        },
        "strokeWidth": {
          "expr": "borderWidth"
        },
        "cornerRadius": {
          "expr": "cardRadius"
        }
      }
    },
    {
      "description": "Title",
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "pad"
        },
        "y": {
          "expr": "titleY"
        },
        "fontSize": {
          "expr": "titleSize"
        },
        "limit": {
          "expr": "width * 0.5"
        },
        "fill": {
          "expr": "labelColor"
        },
        "text": {
          "expr": "title"
        }
      }
    },
    {
      "description": "Share of target: top right in a tile, under the value when stacked",
      "mark": {
        "type": "text",
        "align": {
          "expr": "headAlign"
        },
        "baseline": "alphabetic",
        "fontWeight": "normal",
        "x": {
          "expr": "headX"
        },
        "y": {
          "expr": "headY"
        },
        "fontSize": {
          "expr": "headSize"
        },
        "limit": {
          "expr": "stacked ? width - 2 * pad : width * 0.5 - pad"
        },
        "fill": {
          "expr": "labelColor"
        }
      },
      "encoding": {
        "text": {
          "field": "headText",
          "type": "nominal"
        }
      }
    },
    {
      "description": "Value",
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "alphabetic",
        "fontWeight": "bold",
        "x": {
          "expr": "pad"
        },
        "y": {
          "expr": "valueY"
        },
        "fontSize": {
          "expr": "valueSize"
        },
        "limit": {
          "expr": "stacked ? width - 2 * pad : width * 0.5 - pad"
        },
        "fill": {
          "expr": "valueColor"
        }
      },
      "encoding": {
        "text": {
          "field": "valueText",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Value"
          },
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          },
          {
            "field": "ratioText",
            "type": "nominal",
            "title": "Of target"
          },
          {
            "field": "tipPace",
            "type": "nominal",
            "title": "Pace"
          }
        ]
      }
    },
    {
      "description": "Pace line, or the gap when no pace is bound",
      "mark": {
        "type": "text",
        "align": {
          "expr": "statusAlign"
        },
        "baseline": "alphabetic",
        "fontWeight": 600,
        "x": {
          "expr": "statusX"
        },
        "y": {
          "expr": "statusY"
        },
        "fontSize": {
          "expr": "statusSize"
        },
        "limit": {
          "expr": "stacked ? width * 0.62 - pad : width * 0.5 - pad"
        }
      },
      "encoding": {
        "text": {
          "field": "statusText",
          "type": "nominal"
        },
        "color": {
          "field": "statusColor",
          "type": "nominal",
          "scale": null
        }
      }
    },
    {
      "description": "What is left to go, opposite the pace line (stacked only)",
      "transform": [
        {
          "filter": "length(datum.restText) > 0"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "alphabetic",
        "fontWeight": "normal",
        "x": {
          "expr": "width - pad"
        },
        "y": {
          "expr": "statusY"
        },
        "fontSize": {
          "expr": "statusSize"
        },
        "limit": {
          "expr": "width * 0.38 - pad"
        },
        "fill": {
          "expr": "labelColor"
        }
      },
      "encoding": {
        "text": {
          "field": "restText",
          "type": "nominal"
        }
      }
    },
    {
      "description": "Bar track",
      "mark": {
        "type": "rect",
        "cornerRadius": {
          "expr": "barRadius"
        },
        "fill": {
          "expr": "trackColor"
        }
      },
      "encoding": {
        "x": {
          "field": "bx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "bx1"
        },
        "y": {
          "field": "by0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "by1"
        }
      }
    },
    {
      "description": "Bar fill, to the share of target reached; past 100% the target moves inside the bar",
      "transform": [
        {
          "filter": "datum.fillX > datum.bx0"
        }
      ],
      "mark": {
        "type": "rect",
        "cornerRadius": {
          "expr": "barRadius"
        }
      },
      "encoding": {
        "x": {
          "field": "bx0",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "fillX"
        },
        "y": {
          "field": "by0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "by1"
        },
        "color": {
          "field": "fillColor",
          "type": "nominal",
          "scale": null
        },
        "tooltip": [
          {
            "field": "valueText",
            "type": "nominal",
            "title": "Value"
          },
          {
            "field": "targetText",
            "type": "nominal",
            "title": "Target"
          },
          {
            "field": "ratioText",
            "type": "nominal",
            "title": "Of target"
          },
          {
            "field": "tipPace",
            "type": "nominal",
            "title": "Pace"
          }
        ]
      }
    },
    {
      "description": "Target mark inside an overfull bar",
      "transform": [
        {
          "filter": "datum.r > 1"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": {
          "expr": "2 * unit"
        },
        "stroke": {
          "expr": "cardColor"
        }
      },
      "encoding": {
        "x": {
          "field": "targetX",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "targetX"
        },
        "y": {
          "field": "by0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "by1"
        }
      }
    },
    {
      "description": "Pace marker: where the bar should be by now",
      "transform": [
        {
          "filter": "isValid(datum.paceX)"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeWidth": {
          "expr": "2 * unit"
        },
        "stroke": {
          "expr": "paceColor"
        },
        "strokeCap": "butt"
      },
      "encoding": {
        "x": {
          "field": "paceX",
          "type": "quantitative",
          "scale": null
        },
        "x2": {
          "field": "paceX"
        },
        "y": {
          "field": "py0",
          "type": "quantitative",
          "scale": null
        },
        "y2": {
          "field": "py1"
        },
        "tooltip": [
          {
            "field": "tipPace",
            "type": "nominal",
            "title": "Pace"
          }
        ]
      }
    }
  ]
}'
